import { useMemo, useState } from 'react';
import { ReportModal } from '../components/ReportModal';
import { db, type Profile } from '../db/db';
import { financialTransaction } from '../db/financialAllocation';
import { commercialItemOptions, commercialItemRevenueCents } from '../db/movementAnalysis';
import { classifyCommercialItem, commercialGoalItemMatches, commercialGroupOptions } from '../db/commercialClassification';
import { activityMetricCanUseDonut, activityMetricTotal, activityMetricValue, activityProfitabilityRows, type ActivityMetric, type ActivityProfitabilityRow } from '../db/activityProfitability';
import { addDateDays, dateKey, money } from '../db/managementMath';
import { managementSummary } from '../db/managementSummary';
import { deleteScenario, saveScenario, saveGoal, saveManagementSetting, updateClientGroups } from '../db/managementService';
import type { ManagementGoal } from '../db/managementTypes';
import { centsInput, inputCents, runAction, type ManagementData } from './managementUi';

const fromMoney = (value: number) => money(Math.round(value * 100));
const serviceNames = { key: 'Chaves', plier: 'Alicates', scissor: 'Tesouras', knife: 'Facas', spring: 'Molinhas', screw: 'Parafusos', other: 'Outros', custom: 'Personalizados', plier_sharp: 'Afiação de alicates' };
const viewRows = (data: ManagementData, profile: Profile | 'todos', start: string, end: string) => data.transactions
  .filter(row => { const day = dateKey(new Date(row.date)); return day >= start && day <= end; })
  .map(row => financialTransaction(row, profile)).filter((row): row is NonNullable<typeof row> => row !== null);

export function ManagementSimulator({ data, profile, start, end }: { data: ManagementData; profile: Profile | 'todos'; start: string; end: string }) {
  const [source, setSource] = useState<'real' | 'average' | 'manual'>('real');
  const [objective, setObjective] = useState<'assume' | 'growth' | 'hire' | 'income'>('assume');
  const [advanced, setAdvanced] = useState(false);
  const [months, setMonths] = useState(3);
  const [name, setName] = useState('Novo cenário');
  const [editingId, setEditingId] = useState<number | undefined>();
  const [inputs, setInputs] = useState<Record<string, number>>({ revenue: 0, costs: 0, expenses: 0, wages: 0, fees: 0, workingDays: 26, employees: 0, monthlyPayments: 0, reserves: 0, personalGoal: 0, growth: 0 });
  const [inputRevision, setInputRevision] = useState(0);
  const [showSaved, setShowSaved] = useState(false);
  const loadReal = () => {
    const intervals = source === 'average' ? Array.from({ length: months }, (_, index) => {
      const anchor = new Date(`${start}T12:00:00`);
      anchor.setMonth(anchor.getMonth() - index);
      const month = `${anchor.getFullYear()}-${String(anchor.getMonth() + 1).padStart(2, '0')}`;
      return [month + '-01', dateKey(new Date(anchor.getFullYear(), anchor.getMonth() + 1, 0))];
    }) : [[start, end]];
    const totals = intervals.map(([begin, finish]) => managementSummary(data.transactions, data.entries, data.occurrences, profile, begin, finish));
    const average = (field: 'revenue' | 'costs' | 'operatingExpenses' | 'wages' | 'fees') => Math.round(totals.reduce((sum, row) => sum + row[field], 0) / totals.length * 100);
    setInputs(previous => ({ ...previous, revenue: average('revenue'), costs: average('costs'), expenses: average('operatingExpenses'), wages: average('wages'), fees: average('fees') }));
    setInputRevision(value => value + 1);
  };
  const projectedRevenue = Math.round(inputs.revenue * (1 + inputs.growth / 100));
  const projectedProfit = projectedRevenue - inputs.costs - inputs.expenses - inputs.wages - inputs.fees - inputs.monthlyPayments;
  const availableAfterReserves = projectedProfit - inputs.reserves;
  const requiredRevenue = Math.max(0, inputs.personalGoal + inputs.costs + inputs.expenses + inputs.wages + inputs.fees + inputs.monthlyPayments + inputs.reserves);
  const dailyRequired = Math.ceil(requiredRevenue / Math.max(1, inputs.workingDays));
  const currentProfit = Math.round(managementSummary(data.transactions, data.entries, data.occurrences, profile, start, end).profit * 100);
  const contributionMargin = projectedRevenue ? (projectedRevenue - inputs.costs - inputs.fees) / projectedRevenue * 100 : 0;
  const save = async () => {
    if (await runAction(() => saveScenario({ name, profile, inputs }, editingId), 'Cenário salvo sem alterar os registros oficiais.')) setEditingId(undefined);
  };
  const field = (key: string, label: string, monetary = true) => <label key={key}>{label}<input key={`${key}:${inputRevision}`} type="number" step={monetary ? '0.01' : '1'} defaultValue={monetary ? centsInput(inputs[key] || 0) : inputs[key] || 0} onChange={event => setInputs(previous => ({ ...previous, [key]: monetary ? inputCents(event.target.value) : Number(event.target.value) }))} /></label>;
  const objectives = { assume: 'Simule faturamento, custos e compromissos mensais para estimar o resultado.', growth: 'Veja como o aumento nas vendas pode afetar o resultado.', hire: 'Calcule o impacto de uma nova despesa com funcionário.', income: 'Estime quanto precisa faturar para alcançar a renda desejada.' };
  const relevantFields: Record<typeof objective, [string, string, boolean?][]> = {
    assume: [['revenue','Faturamento líquido previsto'],['costs','Custo dos produtos'],['expenses','Despesas fixas e operacionais'],['wages','Diárias e funcionários'],['fees','Taxas de pagamento'],['monthlyPayments','Novos pagamentos mensais'],['reserves','Reservas planejadas'],['personalGoal','Meta de renda pessoal'],['workingDays','Dias trabalhados',false]],
    growth: [['revenue','Faturamento líquido previsto'],['growth','Crescimento das vendas (%)',false],['costs','Custo dos produtos'],['fees','Taxas de pagamento'],['expenses','Despesas fixas e operacionais']],
    hire: [['revenue','Faturamento líquido previsto'],['costs','Custo dos produtos'],['expenses','Despesas fixas e operacionais'],['wages','Custo mensal de funcionários'],['employees','Quantidade de funcionários',false],['fees','Taxas de pagamento'],['monthlyPayments','Novos pagamentos mensais']],
    income: [['personalGoal','Meta de renda pessoal'],['costs','Custo dos produtos'],['expenses','Despesas fixas e operacionais'],['wages','Diárias e funcionários'],['fees','Taxas de pagamento'],['monthlyPayments','Novos pagamentos mensais'],['reserves','Reservas planejadas'],['workingDays','Dias trabalhados',false]]
  };
  return <div className="mg-section"><div className="mg-heading"><div><h2>Simulador de Gestão</h2><p>Cenários independentes. Nenhum valor daqui cria vendas, despesas ou contas reais.</p></div><button className="btn btn-outline" onClick={() => setShowSaved(true)}>Cenários salvos ({data.scenarios.length})</button></div>
    <div className="mg-card mg-form"><label>Objetivo<select value={objective} onChange={event => setObjective(event.target.value as typeof objective)}><option value="assume">Assumir o estabelecimento</option><option value="growth">Aumentar o faturamento</option><option value="hire">Contratar um funcionário</option><option value="income">Alcançar uma renda desejada</option></select><small>{objectives[objective]}</small></label><label>Base do cenário<select value={source} onChange={event => setSource(event.target.value as typeof source)}><option value="real">Período real selecionado</option><option value="average">Média de meses</option><option value="manual">Totalmente manual</option></select></label>{source === 'average' && <label>Meses considerados<input type="number" min="2" max="24" value={months} onChange={event => setMonths(Math.max(2, Number(event.target.value)))} /></label>}{source !== 'manual' && <button className="btn btn-outline" onClick={loadReal}>Carregar dados reais</button>}
      {relevantFields[objective].map(([key, label, monetary]) => field(key, label, monetary))}<details className="mg-full"><summary>Campos avançados</summary><div className="mg-form">{field('revenue', 'Faturamento líquido previsto')}{field('costs', 'Custo dos produtos')}{field('expenses', 'Despesas fixas e operacionais')}{field('wages', 'Diárias e funcionários')}{field('employees', 'Quantidade de funcionários', false)}{field('fees', 'Taxas de pagamento')}{field('monthlyPayments', 'Novos pagamentos mensais')}{field('reserves', 'Reservas planejadas')}{field('personalGoal', 'Meta de renda pessoal')}{field('workingDays', 'Dias trabalhados', false)}{field('growth', 'Crescimento das vendas (%)', false)}</div></details>
    </div><div className="mg-grid"><div className="mg-card"><small>Resultado líquido projetado</small><strong className="mg-value">{money(projectedProfit)}</strong></div><div className="mg-card"><small>Após reservas planejadas</small><strong className="mg-value">{money(availableAfterReserves)}</strong></div><div className="mg-card"><small>Faturamento necessário para meta</small><strong className="mg-value">{money(requiredRevenue)}</strong><small>{money(dailyRequired)} por dia trabalhado</small></div></div>
    <div className="mg-grid">{[[-10, 'Pessimista'], [0, 'Normal'], [10, 'Otimista']].map(([change, label]) => <div className="mg-card" key={label}><small>{label}: vendas {Number(change) > 0 ? '+' : ''}{change}%</small><strong className="mg-value">{money(Math.round(projectedRevenue * (1 + Number(change) / 100)) - inputs.costs - inputs.expenses - inputs.wages - inputs.fees - inputs.monthlyPayments)}</strong></div>)}</div>
    <div className="mg-card"><p>Margem de contribuição prevista: <strong>{contributionMargin.toFixed(1)}%</strong>. Lucro real do período escolhido: <strong>{money(currentProfit)}</strong>. Diferença projetada: <strong>{money(projectedProfit - currentProfit)}</strong>.</p><p>Capacidade estimada para novos compromissos: <strong>{money(Math.max(0, availableAfterReserves - inputs.personalGoal))}</strong>. Esta simulação depende dos valores informados; não confirma saldo disponível.</p><div className="mg-actions"><input aria-label="Nome do cenário" value={name} onChange={event => setName(event.target.value)} /><button className="btn btn-primary" onClick={save}>{editingId ? 'Atualizar cenário' : 'Salvar cenário'}</button></div></div>
    {showSaved && <ReportModal title="Cenários salvos" onClose={() => setShowSaved(false)} wide><div className="mg-list">{data.scenarios.map(row => <div key={row.id} className="mg-list-row"><span><strong>{row.name}</strong><small>{row.profile === 'todos' ? 'Geral' : row.profile} · {new Date(row.updatedAt).toLocaleDateString('pt-BR')}</small></span><div className="mg-actions"><button onClick={() => { setInputs({ ...row.inputs }); setInputRevision(value => value + 1); setName(row.name); setEditingId(row.id); setShowSaved(false); }}>Abrir</button><button onClick={() => runAction(() => saveScenario({ name: `${row.name} (cópia)`, profile: row.profile, inputs: row.inputs }), 'Cenário duplicado.')}>Duplicar</button><button onClick={() => { if (confirm('Excluir este cenário?')) runAction(() => deleteScenario(row.id!), 'Cenário excluído.'); }}>Excluir</button></div></div>)}{!data.scenarios.length && <p>Nenhum cenário salvo.</p>}</div></ReportModal>}
  </div>;
}

export function ManagementRentability({ data, profile, start, end }: { data: ManagementData; profile: Profile | 'todos'; start: string; end: string }) {
  const [sort, setSort] = useState<'quantity' | 'revenue' | 'cost' | 'margin' | 'result'>('result');
  const [page, setPage] = useState(1);
  const [categoryFilter, setCategoryFilter] = useState('');
  const [nameFilter, setNameFilter] = useState('');
  const [commercialView, setCommercialView] = useState<'overview' | 'products' | 'groups'>('overview');
  const [activityMetric, setActivityMetric] = useState<ActivityMetric>('revenue');
  const [selectedActivity, setSelectedActivity] = useState<ActivityProfitabilityRow | null>(null);
  const [expandedActivityGroup, setExpandedActivityGroup] = useState<string | null>(null);
  const [activityFilter, setActivityFilter] = useState<'all' | 'service' | 'merchandise' | 'review'>('all');
  const [expandedGroup, setExpandedGroup] = useState<string | null>(null);
  const [editingProduct, setEditingProduct] = useState<{ id: number; activity: 'service' | 'merchandise'; group: string } | null>(null);
  const rows = useMemo(() => {
    const grouped = new Map<string, { key: string; productId?: number; activity?: 'service' | 'merchandise'; group: string; name: string; quantity: number; revenueCents: number; costCents: number; replacementCents: number; costKnown: boolean; replacementKnown: boolean; reserveEligible: boolean }>();
    for (const transaction of viewRows(data, profile, start, end)) {
      if (transaction.type !== 'sale' && transaction.type !== 'return') continue;
      const sign = transaction.type === 'sale' ? 1 : -1;
      const itemRevenue = commercialItemRevenueCents(transaction);
      transaction.items.forEach((item, index) => {
        if (categoryFilter && item.service !== categoryFilter) return;
        if (nameFilter && !item.name.toLocaleLowerCase('pt-BR').includes(nameFilter.toLocaleLowerCase('pt-BR'))) return;
        const key = item.productId ? `produto:${item.productId}` : `manual:${item.service}:${item.name}:${item.financialProfile || transaction.profile}`;
        const product = data.products.find(candidate => candidate.id === item.productId);
        const { activity, group: suggestedGroup } = classifyCommercialItem(item, product);
        const current = grouped.get(key) || { key, productId: item.productId, activity, group: suggestedGroup, name: item.name, quantity: 0, revenueCents: 0, costCents: 0, replacementCents: 0, costKnown: true, replacementKnown: true, reserveEligible: !!product?.reserveForRestock };
        current.quantity += sign * item.quantity;
        current.revenueCents += sign * itemRevenue[index];
        current.costCents += sign * Math.round((item.cost || 0) * item.quantity * 100);
        if (item.replacementCost === undefined) current.replacementKnown = false;
        else current.replacementCents += sign * Math.round(item.replacementCost * item.quantity * 100);
        const catalogProduct = data.products.find(product => product.id === item.productId);
        if (item.cost === undefined || item.cost === null || (item.cost === 0 && catalogProduct?.hasStock)) current.costKnown = false;
        grouped.set(key, current);
      });
    }
    return [...grouped.values()].map(row => ({ ...row, resultCents: row.revenueCents - row.costCents, replacementResultCents: row.revenueCents - row.replacementCents, replenishmentGapCents: row.replacementCents - row.costCents, margin: row.revenueCents ? (row.revenueCents - row.costCents) / row.revenueCents * 100 : 0, replacementMargin: row.revenueCents ? (row.revenueCents - row.replacementCents) / row.revenueCents * 100 : 0, restockReserveCents: row.replacementKnown && row.reserveEligible ? row.replacementCents : 0 })).filter(row => activityFilter === 'all' || (activityFilter === 'review' ? row.group === 'Precisa classificar' : row.activity === activityFilter)).sort((a, b) => a.costKnown !== b.costKnown ? Number(b.costKnown) - Number(a.costKnown) : sort === 'quantity' ? b.quantity - a.quantity : sort === 'revenue' ? b.revenueCents - a.revenueCents : sort === 'cost' ? b.costCents - a.costCents : sort === 'margin' ? b.margin - a.margin : b.resultCents - a.resultCents);
  }, [data, profile, start, end, sort, categoryFilter, nameFilter, activityFilter]);
  const totalRevenue = rows.reduce((sum, row) => sum + row.revenueCents, 0);
  const activityRows = useMemo(() => activityProfitabilityRows(data.transactions, data.products, profile, start, end), [data.transactions, data.products, profile, start, end]);
  const activityTotal = activityMetricTotal(activityRows, activityMetric);
  const activityMarginAvailable = activityMetricTotal(activityRows, 'margin') !== null;
  const activityDonutReady = activityMetricCanUseDonut(activityRows, activityMetric);
  const metricLabel = activityMetric === 'revenue' ? 'Faturamento' : activityMetric === 'units' ? 'Unidades' : 'Margem bruta';
  const metricValueLabel = (row: ActivityProfitabilityRow) => {
    const value = activityMetricValue(row, activityMetric);
    if (value === null) return 'Indisponível';
    return activityMetric === 'units' ? `${value} un.` : money(value);
  };
  const metricShareLabel = (row: ActivityProfitabilityRow) => {
    const value = activityMetricValue(row, activityMetric);
    return value === null || activityTotal === null || activityTotal === 0 ? '—' : `${(value / activityTotal * 100).toFixed(1).replace('.', ',')}%`;
  };
  const donutSegments = activityRows.map(row => ({ row, value: Math.max(0, activityMetricValue(row, activityMetric) || 0) })).filter(segment => segment.value > 0);
  const donutStyle = (() => {
    if (!activityDonutReady || !activityTotal) return undefined;
    let cursor = 0;
    const stops = donutSegments.map(({ row, value }) => {
      const from = cursor / activityTotal * 100;
      cursor += value;
      return `${row.color} ${from}% ${cursor / activityTotal * 100}%`;
    });
    return { background: `conic-gradient(${stops.join(', ')})` };
  })();  const suggestedReserve = rows.reduce((sum, row) => sum + (row.reserveEligible && row.replacementKnown ? row.restockReserveCents : 0), 0);
  const periodStart = new Date(`${start}T00:00:00`);
  const periodEnd = new Date(`${addDateDays(end, 1)}T00:00:00`);
  const actualReserve = data.entries.filter(entry => entry.kind === 'fund-deposit' && entry.note?.startsWith('Reserva de reposição no fechamento') && entry.date >= periodStart && entry.date < periodEnd && (profile === 'todos' || entry.profile === profile)).reduce((sum, entry) => sum + entry.amountCents, 0);
  const categories = [...new Set(data.transactions.flatMap(row => row.items.map(item => item.service)))];
  const groups = [...new Set(rows.map(row => `${row.activity || 'review'}:${row.group}`))].map(key => {
    const products = rows.filter(row => `${row.activity || 'review'}:${row.group}` === key);
    return { key, products, name: products[0].group, activity: products[0].activity, quantity: products.reduce((sum, row) => sum + row.quantity, 0), revenue: products.reduce((sum, row) => sum + row.revenueCents, 0), cost: products.reduce((sum, row) => sum + row.costCents, 0), result: products.reduce((sum, row) => sum + row.resultCents, 0), costKnown: products.every(row => row.costKnown) };
  }).sort((a, b) => b.revenue - a.revenue);
  const saveClassification = async () => {
    if (!editingProduct) return;
    await db.products.update(editingProduct.id, { commercialActivity: editingProduct.activity, commercialGroup: editingProduct.group.trim() || 'Outros' });
    setEditingProduct(null);
  };
  return <div className="mg-section">
    <div className="mg-heading"><div><h2>Rentabilidade</h2><p>Margem por item antes das despesas gerais. Nenhuma despesa geral é atribuída arbitrariamente a produtos.</p></div><label>Ordenar por <select value={sort} onChange={event => { setSort(event.target.value as typeof sort); setPage(1); }}><option value="result">Resultado bruto</option><option value="quantity">Quantidade</option><option value="revenue">Receita</option><option value="cost">Custo</option><option value="margin">Margem</option></select></label></div>
    <div className="mg-grid"><div className="mg-card"><small>Reserva de reposição estimada</small><strong className="mg-value">{money(suggestedReserve)}</strong></div><div className="mg-card"><small>Reserva efetivamente constituída no período</small><strong className="mg-value">{money(actualReserve)}</strong></div><div className="mg-card"><small>Itens sem custo padrão histórico</small><strong className="mg-value">{rows.filter(row => !row.replacementKnown).length}</strong></div></div>
    <div className="mg-subtabs"><button className={commercialView === 'overview' ? 'active' : ''} onClick={() => setCommercialView('overview')}>Visão por atividade</button><button className={commercialView === 'products' ? 'active' : ''} onClick={() => setCommercialView('products')}>Produtos individuais</button><button className={commercialView === 'groups' ? 'active' : ''} onClick={() => setCommercialView('groups')}>Atividades e grupos</button></div>
    {commercialView === 'overview' && <section className="mg-activity-overview" aria-label="Rentabilidade por atividade"><div className="mg-actions mg-activity-metrics"><strong>{metricLabel}</strong><button className={activityMetric === 'revenue' ? 'active' : ''} onClick={() => setActivityMetric('revenue')}>Faturamento</button><button className={activityMetric === 'units' ? 'active' : ''} onClick={() => setActivityMetric('units')}>Unidades</button><button disabled={!activityMarginAvailable} className={activityMetric === 'margin' ? 'active' : ''} onClick={() => setActivityMetric('margin')}>Margem bruta</button></div><div className="mg-activity-layout"><div className="mg-card mg-activity-chart-card"><div className="mg-activity-donut-wrap">{donutStyle ? <div className="mg-activity-donut" style={donutStyle} role="img" aria-label={`Distribuição por ${metricLabel.toLocaleLowerCase('pt-BR')}`}><div><small>Total</small><strong>{activityTotal === null ? 'Indisponível' : activityMetric === 'units' ? `${activityTotal} un.` : money(activityTotal)}</strong></div></div> : <div className="mg-activity-empty">{activityTotal === null ? 'Margem indisponível: há itens sem custo conhecido.' : 'Não há valores positivos para compor o gráfico.'}</div>}</div><div className="mg-activity-legend">{activityRows.map(row => <button key={row.key} disabled={!(activityMetricValue(row, activityMetric) || 0)} onClick={() => setSelectedActivity(row)}><i style={{ background: row.color }} /><span>{row.label}</span><strong>{metricValueLabel(row)}</strong><small>{metricShareLabel(row)}</small></button>)}</div></div><div className="mg-card mg-activity-total-card"><small>Total do período filtrado</small><strong className="mg-value">{activityTotal === null ? 'Indisponível' : activityMetric === 'units' ? `${activityTotal} un.` : money(activityTotal)}</strong><small>Valores conciliados por venda e devolução no período e operador selecionados.</small><div className="mg-activity-breakdown">{activityRows.map(row => <button key={row.key} onClick={() => setSelectedActivity(row)}><span>{row.label}</span><strong>{metricValueLabel(row)}</strong><small>{metricShareLabel(row)}</small></button>)}</div></div></div></section>}
    <div className="mg-actions"><label>Atividade<select value={activityFilter} onChange={event => { setActivityFilter(event.target.value as typeof activityFilter); setPage(1); }}><option value="all">Todas</option><option value="service">Serviços</option><option value="merchandise">Venda de mercadorias</option><option value="review">Precisa classificar</option></select></label><label>Produto/serviço<input placeholder="Filtrar nome" value={nameFilter} onChange={event => { setNameFilter(event.target.value); setPage(1); }} /></label><label>Categoria<select value={categoryFilter} onChange={event => { setCategoryFilter(event.target.value); setPage(1); }}><option value="">Todas</option>{categories.map(category => <option key={category} value={category}>{serviceNames[category as keyof typeof serviceNames] || category}</option>)}</select></label></div>
    {commercialView === 'groups' && <><div className="mg-grid mg-grid-two">{(['service', 'merchandise'] as const).map(activity => { const list = rows.filter(row => row.activity === activity); const total = list.reduce((sum, row) => sum + row.revenueCents, 0); return <div className="mg-card" key={activity}><small>{activity === 'service' ? 'Serviços' : 'Venda de mercadorias'}</small><strong className="mg-value">{money(total)}</strong><small>{list.reduce((sum, row) => sum + row.quantity, 0)} unidades · {totalRevenue ? (total / totalRevenue * 100).toFixed(1).replace('.', ',') : '0,0'}% do faturamento filtrado</small></div>; })}</div><div className="mg-group-list">{groups.map(group => <div className="mg-card mg-commercial-group" key={group.key}><button className="mg-commercial-group-head" onClick={() => setExpandedGroup(expandedGroup === group.key ? null : group.key)}><span><strong>{group.name}</strong><small>{group.activity === 'service' ? 'Serviços' : group.activity === 'merchandise' ? 'Venda de mercadorias' : 'Conferência pendente'} · {group.products.length} produtos/itens</small></span><span><strong>{money(group.revenue)}</strong><small>{group.quantity} un. · {totalRevenue ? (group.revenue / totalRevenue * 100).toFixed(1).replace('.', ',') : '0,0'}% do faturamento filtrado</small></span></button><div className="mg-group-bar"><i style={{ width: (totalRevenue ? Math.max(0, Math.min(100, group.revenue / totalRevenue * 100)) : 0) + '%' }} /></div><small>Custo {group.costKnown ? money(group.cost) : 'há itens sem base'} · resultado {group.costKnown ? money(group.result) : 'parcial, custo não informado'} · margem {group.costKnown && group.revenue ? (group.result / group.revenue * 100).toFixed(1) + '%' : 'indisponível'}</small>{expandedGroup === group.key && <div className="mg-table-wrap"><table className="mg-table"><thead><tr><th>Produto individual</th><th>Qtd.</th><th>Receita</th><th>Participação</th><th>Classificação</th></tr></thead><tbody>{group.products.map(product => <tr key={product.key}><td>{product.name}</td><td>{product.quantity}</td><td>{money(product.revenueCents)}</td><td>{totalRevenue ? (product.revenueCents / totalRevenue * 100).toFixed(1).replace('.', ',') : '0,0'}%</td><td>{product.productId ? <button className="mg-link" onClick={() => { const item = data.products.find(row => row.id === product.productId)!; setEditingProduct({ id: item.id!, activity: product.activity || 'merchandise', group: product.group === 'Precisa classificar' ? '' : product.group }); }}>Conferir/editar</button> : 'Item sem cadastro individual'}</td></tr>)}</tbody></table></div>}</div>)}</div></>}
    {commercialView === 'products' && <div className="mg-card mg-table-wrap"><table className="mg-table"><thead><tr><th>Produto ou serviço</th><th>Atividade / grupo</th><th>Qtd.</th><th>Receita</th><th>Custo aquisição</th><th>Resultado aquisição</th><th>Custo padrão</th><th>Resultado padrão</th><th>Diferença</th><th>Reserva reposição</th><th>Margem aquisição</th><th>Margem padrão</th><th>Participação</th></tr></thead><tbody>{rows.slice((page - 1) * 20, page * 20).map((row, index) => <tr key={row.name + ':' + index}><td>{row.name}{!row.costKnown && <small>Custo não informado</small>}</td><td>{row.activity === 'service' ? 'Serviço' : row.activity === 'merchandise' ? 'Mercadoria' : 'Conferir'} · {row.group}{row.productId && <button className="mg-link" onClick={() => { const item = data.products.find(product => product.id === row.productId)!; setEditingProduct({ id: item.id!, activity: row.activity || 'merchandise', group: row.group === 'Precisa classificar' ? '' : row.group }); }}>Editar</button>}</td><td>{row.quantity}</td><td>{money(row.revenueCents)}</td><td>{row.costKnown ? money(row.costCents) : 'Sem base'}</td><td>{row.costKnown ? money(row.resultCents) : 'Sem base'}</td><td>{row.replacementKnown ? money(row.replacementCents) : 'Sem custo padrão'}</td><td>{row.replacementKnown ? money(row.replacementResultCents) : 'Sem base'}</td><td>{row.replacementKnown ? money(row.replenishmentGapCents) : 'Sem base'}</td><td>{row.reserveEligible && row.replacementKnown ? money(row.restockReserveCents) : 'Não selecionado'}</td><td>{row.costKnown ? row.margin.toFixed(1) + '%' : 'Sem base'}</td><td>{row.replacementKnown ? row.replacementMargin.toFixed(1) + '%' : 'Sem base'}</td><td>{totalRevenue ? (row.revenueCents / totalRevenue * 100).toFixed(1) : '0,0'}%</td></tr>)}{!rows.length && <tr><td colSpan={13}>Sem vendas vinculadas no período.</td></tr>}</tbody></table></div>}
    {commercialView === 'products' && rows.length > 20 && <div className="mg-pagination"><button disabled={page === 1} onClick={() => setPage(page - 1)}>Anterior</button><span>{page} / {Math.ceil(rows.length / 20)}</span><button disabled={page >= Math.ceil(rows.length / 20)} onClick={() => setPage(page + 1)}>Próxima</button></div>}
    {editingProduct && <ReportModal title="Classificação comercial do produto" onClose={() => setEditingProduct(null)}><form className="mg-form" onSubmit={event => { event.preventDefault(); void saveClassification(); }}><label>Tipo de atividade<select value={editingProduct.activity} onChange={event => setEditingProduct({ ...editingProduct, activity: event.target.value as typeof editingProduct.activity })}><option value="service">Serviço</option><option value="merchandise">Venda de mercadoria</option></select></label><label>Grupo comercial<input required value={editingProduct.group} onChange={event => setEditingProduct({ ...editingProduct, group: event.target.value })} placeholder="Ex.: Cópias de chaves comuns" /></label><p className="mg-full mg-hint">Esta classificação afeta somente a análise gerencial. Não mescla produtos nem altera estoque, custos ou baixas.</p><div className="mg-full mg-actions"><button className="btn btn-primary">Salvar classificação</button></div></form></ReportModal>}
    {selectedActivity && <ReportModal title={selectedActivity.label} subtitle={`${metricLabel}: ${metricValueLabel(selectedActivity)} · ${metricShareLabel(selectedActivity)} do total`} onClose={() => { setSelectedActivity(null); setExpandedActivityGroup(null); }} wide><div className="mg-activity-detail"><div className="mg-activity-detail-total"><span>Faturamento</span><strong>{money(selectedActivity.revenueCents)}</strong><span>Unidades</span><strong>{selectedActivity.quantity}</strong><span>Custo identificado</span><strong>{selectedActivity.costKnown ? money(selectedActivity.costCents) : 'Incompleto'}</strong><span>Margem bruta</span><strong>{selectedActivity.marginCents === null ? 'Indisponível' : money(selectedActivity.marginCents)}</strong></div>{selectedActivity.groups.map(group => <section className="mg-activity-detail-group" key={group.key}><button onClick={() => setExpandedActivityGroup(expandedActivityGroup === group.key ? null : group.key)}><span><strong>{group.name}</strong><small>{group.items.length} itens cadastrados</small></span><span><strong>{money(group.revenueCents)}</strong><small>{group.quantity} unidades</small></span></button>{expandedActivityGroup === group.key && <div className="mg-table-wrap"><table className="mg-table"><thead><tr><th>Produto/serviço</th><th>Código</th><th>Qtd.</th><th>Faturamento</th><th>Custo</th><th>Margem</th></tr></thead><tbody>{group.items.map(item => <tr key={item.key}><td>{item.name}</td><td>{item.code || '—'}</td><td>{item.quantity}</td><td>{money(item.revenueCents)}</td><td>{item.costKnown ? money(item.costCents) : 'Sem base'}</td><td>{item.costKnown ? money(item.revenueCents - item.costCents) : 'Indisponível'}</td></tr>)}</tbody></table></div>}</section>)}{!selectedActivity.groups.length && <p>Não há lançamentos para esta atividade no período filtrado.</p>}</div></ReportModal>}
  </div>;
}

export { ManagementMovement } from './ManagementMovement';

export function ManagementInventory({ data, profile, start, end }: { data: ManagementData; profile: Profile | 'todos'; start: string; end: string }) {
  const [inactiveDays, setInactiveDays] = useState(Number(data.settings.find(row => row.key === 'inventoryInactiveDays')?.value || 90));
  const [coverageDays, setCoverageDays] = useState(Number(data.settings.find(row => row.key === 'inventoryCoverageDays')?.value || 14));
  const [page, setPage] = useState(1);
  const [historyId, setHistoryId] = useState<number | null>(null);
  const [historyPage, setHistoryPage] = useState(1);
  const products = data.products.filter(row => row.hasStock && (profile === 'todos' || row.profile === profile));
  const cutoff = addDateDays(dateKey(new Date()), -inactiveDays);
  const periodDays = Math.max(1, Math.round((+new Date(`${end}T12:00:00`) - +new Date(`${start}T12:00:00`)) / 86400000) + 1);
  const movements = viewRows(data, profile, start, end).filter(row => row.type === 'sale' || row.type === 'return');
  const rows = products.map(product => {
    const sold = movements.reduce((sum, transaction) => sum + (transaction.type === 'sale' ? 1 : -1) * transaction.items.filter(item => item.productId === product.id).reduce((value, item) => value + item.quantity, 0), 0);
    const last = data.transactions.filter(row => row.type === 'sale' && row.items.some(item => item.productId === product.id)).sort((a, b) => +new Date(b.date) - +new Date(a.date))[0];
    const min = product.idealStock || 0;
    const average = Math.max(0, sold / periodDays);
    const suggested = Math.max(0, min - product.stock, Math.ceil(average * coverageDays) - product.stock);
    return { product, sold, average, lastDate: last ? dateKey(new Date(last.date)) : '', low: min > 0 && product.stock < min, inactive: !last || dateKey(new Date(last.date)) < cutoff, suggested };
  }).sort((a, b) => Number(b.low) - Number(a.low) || a.product.stock - b.product.stock);
  const capital = rows.reduce((sum, row) => sum + row.product.stock * row.product.costPrice, 0);
  const selected = rows.find(row => row.product.id === historyId);
  const history = historyId === null ? [] : [...movements.flatMap(transaction => transaction.items.filter(item => item.productId === historyId).map(item => ({ date: transaction.date, kind: transaction.type, quantity: item.quantity, amountCents: Math.round(item.total * 100), acquisitionCents: Math.round((item.cost || 0) * item.quantity * 100), replacementCents: item.replacementCost === undefined ? undefined : Math.round(item.replacementCost * item.quantity * 100) }))), ...data.purchases.filter(row => row.productId === historyId && row.date >= new Date(`${start}T00:00:00`) && row.date < new Date(`${addDateDays(end, 1)}T00:00:00`)).map(row => ({ date: row.date, kind: "purchase" as const, quantity: row.quantity, amountCents: row.totalCents, acquisitionCents: row.totalCents, replacementCents: undefined })), ...data.costHistory.filter(row => row.productId === historyId && row.at >= new Date(`${start}T00:00:00`) && row.at < new Date(`${addDateDays(end, 1)}T00:00:00`)).map(row => ({ date: row.at, kind: "cost" as const, quantity: undefined, amountCents: undefined, acquisitionCents: row.acquisitionCostCents, replacementCents: row.replacementCostCents }))].sort((a, b) => +new Date(b.date) - +new Date(a.date));
  return <div className="mg-section">
    <div className="mg-heading"><div><h2>Estoque gerencial</h2><p>Consulta o estoque existente. Sugestões são estimativas e não alteram quantidades.</p></div><div className="mg-actions"><label>Sem movimento há <input type="number" min="1" value={inactiveDays} onChange={event => { const value = Math.max(1, Number(event.target.value)); setInactiveDays(value); void saveManagementSetting('inventoryInactiveDays', value); }} /> dias</label><label>Cobertura estimada <input type="number" min="1" value={coverageDays} onChange={event => { const value = Math.max(1, Number(event.target.value)); setCoverageDays(value); void saveManagementSetting('inventoryCoverageDays', value); }} /> dias</label></div></div>
    <div className="mg-grid"><div className="mg-card"><small>Capital registrado em estoque pelo custo de aquisição</small><strong className="mg-value">{fromMoney(capital)}</strong></div><div className="mg-card"><small>Produtos sem custo de aquisição</small><strong className="mg-value">{rows.filter(row => row.product.costPrice <= 0).length}</strong></div><div className="mg-card"><small>Produtos sem custo padrão de reposição</small><strong className="mg-value">{rows.filter(row => row.product.replacementCostCents === undefined).length}</strong></div><div className="mg-card"><small>Produtos abaixo do mínimo</small><strong className="mg-value">{rows.filter(row => row.low).length}</strong></div><div className="mg-card"><small>Produtos sem movimento</small><strong className="mg-value">{rows.filter(row => row.inactive).length}</strong></div></div>
    <div className="mg-card mg-table-wrap"><table className="mg-table"><thead><tr><th>Produto</th><th>Perfil</th><th>Estoque</th><th>Mínimo</th><th>Vendido no período</th><th>Consumo médio</th><th>Giro simples</th><th>Última venda</th><th>Reposição estimada</th><th></th></tr></thead><tbody>{rows.slice((page - 1) * 20, page * 20).map(({ product, sold, average, lastDate, low, suggested }) => <tr key={product.id}><td>{product.name}{low && <small className="mg-warning">Abaixo do mínimo</small>}</td><td>{product.profile === 'chaveiro' ? 'Chaveiro' : 'Fabiano'}</td><td>{product.stock}</td><td>{product.idealStock ?? 'Não definido'}</td><td>{sold}</td><td>{average.toFixed(2)} un./dia</td><td>{product.stock > 0 ? (sold / product.stock).toFixed(2) : 'Sem base'}</td><td>{lastDate ? lastDate.split('-').reverse().join('/') : 'Sem registro'}</td><td>{suggested ? `${suggested} un.` : '—'}</td><td><button className="mg-link" onClick={() => { setHistoryId(product.id!); setHistoryPage(1); }}>Movimento</button></td></tr>)}{!rows.length && <tr><td colSpan={10}>Nenhum produto de estoque no filtro.</td></tr>}</tbody></table></div>
    {rows.length > 20 && <div className="mg-pagination"><button disabled={page === 1} onClick={() => setPage(page - 1)}>Anterior</button><span>{page} / {Math.ceil(rows.length / 20)}</span><button disabled={page >= Math.ceil(rows.length / 20)} onClick={() => setPage(page + 1)}>Próxima</button></div>}
    <p className="mg-hint">Giro simples = unidades vendidas no período ÷ estoque atual; não substitui giro contábil. A sugestão considera mínimo e consumo médio no período. Entradas e ajustes manuais antigos não possuem histórico completo aqui; use a tela Estoque para configurar o mínimo.</p>
    {selected && <ReportModal title={`Custos e movimento de ${selected.product.name}`} subtitle={`${start.split("-").reverse().join("/")} a ${end.split("-").reverse().join("/")}`} onClose={() => setHistoryId(null)} wide><div className="mg-card mg-table-wrap"><table className="mg-table"><thead><tr><th>Data</th><th>Movimento</th><th>Quantidade</th><th>Valor registrado</th><th>Custo de aquisição</th><th>Custo padrão vigente na venda</th></tr></thead><tbody>{history.slice((historyPage - 1) * 20, historyPage * 20).map((row, index) => <tr key={`${row.date}:${row.kind}:${index}`}><td>{new Date(row.date).toLocaleString("pt-BR")}</td><td>{row.kind === "sale" ? "Venda" : row.kind === "return" ? "Devolução" : row.kind === "purchase" ? "Compra registrada" : "Histórico de custos"}</td><td>{row.quantity ?? "—"}</td><td>{row.amountCents === undefined ? "—" : fromMoney(row.amountCents)}</td><td>{fromMoney(row.acquisitionCents)}</td><td>{row.replacementCents === undefined ? "Sem custo padrão" : fromMoney(row.replacementCents)}</td></tr>)}{!history.length && <tr><td colSpan={6}>Sem compras, alterações de custo ou movimentos do produto no período.</td></tr>}</tbody></table></div>{history.length > 20 && <div className="mg-pagination"><button disabled={historyPage === 1} onClick={() => setHistoryPage(value => value - 1)}>Anterior</button><span>{historyPage} / {Math.ceil(history.length / 20)}</span><button disabled={historyPage >= Math.ceil(history.length / 20)} onClick={() => setHistoryPage(value => value + 1)}>Próxima</button></div>}</ReportModal>}
  </div>;
}
export function ManagementClients({ data }: { data: ManagementData }) {
  const [editing, setEditing] = useState<number | null>(null);
  const [groups, setGroups] = useState('');
  const [notes, setNotes] = useState('');
  const [page, setPage] = useState(1);
  const [search, setSearch] = useState('');
  const rows = data.clients.filter(client => client.name.toLowerCase().includes(search.toLowerCase()) || client.code.toLowerCase().includes(search.toLowerCase())).map(client => {
    const linked = data.transactions.filter(row => row.type === 'sale' && (row.clientId === client.id || (client.code && row.clientCode === client.code)));
    const last = linked.sort((a, b) => +new Date(b.date) - +new Date(a.date))[0];
    const spent = linked.reduce((sum, row) => sum + row.total, 0);
    return { client, visits: linked.length, last, spent, ticket: linked.length ? spent / linked.length : 0 };
  }).sort((a, b) => b.visits - a.visits);
  return <div className="mg-section"><div className="mg-heading"><div><h2>Clientes e fidelização</h2><p>Usa o cadastro existente. Vendas sem ID ou código inequívoco não são atribuídas por semelhança de nomes.</p></div><input aria-label="Buscar cliente" placeholder="Buscar cliente" value={search} onChange={event => { setSearch(event.target.value); setPage(1); }} /></div><div className="mg-grid"><div className="mg-card"><small>Clientes cadastrados</small><strong className="mg-value">{data.clients.length}</strong></div><div className="mg-card"><small>Clientes recorrentes identificados</small><strong className="mg-value">{rows.filter(row => row.visits > 1).length}</strong></div><div className="mg-card"><small>Sem retorno em 90 dias, com histórico vinculado</small><strong className="mg-value">{rows.filter(row => row.last && +new Date(row.last.date) < +new Date(addDateDays(dateKey(new Date()), -90) + 'T00:00:00')).length}</strong></div></div><div className="mg-card mg-table-wrap"><table className="mg-table"><thead><tr><th>Cliente</th><th>Grupos</th><th>Atendimentos</th><th>Última visita</th><th>Total gasto</th><th>Ticket médio</th><th></th></tr></thead><tbody>{rows.slice((page - 1) * 20, page * 20).map(({ client, visits, last, spent, ticket }) => <tr key={client.id}><td>{client.name}<small>{client.code || 'Sem código'}</small></td><td>{client.groups?.join(', ') || '—'}</td><td>{visits || 'Sem vínculo confiável'}</td><td>{last ? new Date(last.date).toLocaleDateString('pt-BR') : '—'}</td><td>{fromMoney(spent)}</td><td>{fromMoney(ticket)}</td><td><button className="mg-link" onClick={() => { setEditing(client.id!); setGroups(client.groups?.join(', ') || ''); setNotes(client.notes || ''); }}>Categorias</button></td></tr>)}{!rows.length && <tr><td colSpan={7}>Nenhum cliente encontrado.</td></tr>}</tbody></table></div>{rows.length > 20 && <div className="mg-pagination"><button disabled={page === 1} onClick={() => setPage(page - 1)}>Anterior</button><span>{page} / {Math.ceil(rows.length / 20)}</span><button disabled={page >= Math.ceil(rows.length / 20)} onClick={() => setPage(page + 1)}>Próxima</button></div>}{editing && <ReportModal title="Categorias do cliente" onClose={() => setEditing(null)}><form className="mg-form" onSubmit={async event => { event.preventDefault(); if (await runAction(() => updateClientGroups(editing, groups.split(','), notes))) setEditing(null); }}><label className="mg-full">Grupos personalizados (separados por vírgula)<input value={groups} onChange={event => setGroups(event.target.value)} placeholder="Comercial, Salão, Manicure, Curso" /></label><label className="mg-full">Informações complementares<textarea value={notes} onChange={event => setNotes(event.target.value)} /></label><p className="mg-full mg-hint">Nenhum cadastro é mesclado automaticamente.</p><div className="mg-full mg-actions"><button className="btn btn-primary">Salvar</button></div></form></ReportModal>}</div>;
}

export function ManagementGoals({ data, profile, start, end }: { data: ManagementData; profile: Profile | 'todos'; start: string; end: string }) {
  const [form, setForm] = useState<ManagementGoal | null>(null);
  const goals = data.goals.filter(row => profile === 'todos' || row.profile === profile);
  const newGoal = (): ManagementGoal => ({ name: '', profile: profile === 'todos' ? 'chaveiro' : profile, kind: 'revenue', target: 0, period: 'monthly', workingDays: [1,2,3,4,5,6], status: 'active', createdAt: new Date(), updatedAt: new Date() });
  const progress = (goal: ManagementGoal) => {
    const begin = goal.period === 'daily' ? dateKey(new Date()) : goal.period === 'monthly' ? dateKey(new Date(new Date().getFullYear(), new Date().getMonth(), 1)) : goal.startDate || start;
    const finish = goal.period === 'daily' ? begin : goal.period === 'monthly' ? dateKey(new Date(new Date().getFullYear(), new Date().getMonth() + 1, 0)) : goal.endDate || end;
    const stats = managementSummary(data.transactions, data.entries, data.occurrences, goal.profile, begin, finish);
    const goalRows = viewRows(data, goal.profile, begin, finish).filter(row => row.type === 'sale' || row.type === 'return');
    const matchesGoalItem = (item: Transaction['items'][number]) => ['services', 'key_copies', 'plier_sharpening', 'category'].includes(goal.kind)
      ? commercialGoalItemMatches(item, data.products.find(product => product.id === item.productId), goal.kind as 'services' | 'key_copies' | 'plier_sharpening' | 'category', goal.category)
      : true;
    const achieved = goal.kind === 'revenue' ? inputCents(String(stats.revenue)) : goal.kind === 'profit' ? inputCents(String(stats.profit)) : goal.kind === 'reserve' ? inputCents(String(stats.reserved)) : goal.kind === 'sales_count' ? goalRows.filter(row => row.type === 'sale').length : goalRows.reduce((sum, row) => sum + (row.type === 'sale' ? 1 : -1) * row.items.filter(matchesGoalItem).reduce((value, item) => value + item.quantity, 0), 0);
    let daysLeft = 0;
    for (let day = dateKey(new Date()) < begin ? begin : dateKey(new Date()); day <= finish && daysLeft < 370; day = addDateDays(day, 1)) if ((goal.workingDays || [1,2,3,4,5,6]).includes(new Date(`${day}T12:00:00`).getDay())) daysLeft++;
    return { achieved, daysLeft };
  };
  const goalGroups = commercialGroupOptions(commercialItemOptions(data.transactions, data.products));
  return <div className="mg-section"><div className="mg-heading"><div><h2>Metas</h2><p>As metas acompanham o resultado e nunca bloqueiam o PDV.</p></div><button className="btn btn-primary" onClick={() => setForm(newGoal())}>Nova meta</button></div><div className="mg-grid">{goals.map(goal => { const { achieved, daysLeft } = progress(goal); const monetary = ['revenue','profit','reserve'].includes(goal.kind); const percentage = goal.target ? Math.max(0, Math.round(achieved / goal.target * 100)) : 0; const missing = Math.max(0, goal.target - achieved); return <div className="mg-card" key={goal.id}><div className="mg-heading"><h3>{goal.name}</h3><button className="mg-link" onClick={() => setForm({ ...goal })}>Editar</button></div><small>{goal.profile} · {goal.period === 'daily' ? 'Diária' : goal.period === 'monthly' ? 'Mensal' : 'Personalizada'} · {({ active: 'Ativa', inactive: 'Inativa', archived: 'Arquivada' })[goal.status]}</small><strong className="mg-value">{monetary ? money(achieved) : achieved} / {monetary ? money(goal.target) : goal.target}</strong><div className="mg-progress"><span style={{ width: `${Math.min(100, percentage)}%` }} /></div><small>{percentage}% · Restam {monetary ? money(missing) : missing} · {daysLeft} dia(s) de funcionamento · média necessária {monetary ? money(Math.ceil(missing / Math.max(1, daysLeft))) : Math.ceil(missing / Math.max(1, daysLeft))}/dia</small></div>; })}</div>{!goals.length && <div className="mg-card">Nenhuma meta cadastrada.</div>}{form && <ReportModal title={form.id ? 'Editar meta' : 'Nova meta'} onClose={() => setForm(null)}><form className="mg-form" onSubmit={async event => { event.preventDefault(); const { id, createdAt, updatedAt, ...input } = form; void createdAt; void updatedAt; if (await runAction(() => saveGoal(input, id))) setForm(null); }}><label>Nome<input required value={form.name} onChange={event => setForm({ ...form, name: event.target.value })} /></label><label>Perfil<select value={form.profile} onChange={event => setForm({ ...form, profile: event.target.value as Profile })}><option value="chaveiro">Chaveiro</option><option value="fabiano">Fabiano</option></select></label><label>Tipo<select value={form.kind} onChange={event => setForm({ ...form, kind: event.target.value as ManagementGoal['kind'], category: event.target.value === 'category' ? form.category || 'key' : form.category })}><option value="revenue">Faturamento</option><option value="profit">Lucro</option><option value="services">Quantidade de serviços</option><option value="sales_count">Quantidade de vendas</option><option value="item_count">Produtos vendidos</option><option value="key_copies">Chaves confeccionadas</option><option value="plier_sharpening">Alicates afiados</option><option value="category">Categoria</option><option value="reserve">Reserva</option></select></label>{form.kind === 'category' && <label>Categoria<select value={form.category || 'key'} onChange={event => setForm({ ...form, category: event.target.value })}>{Object.entries(serviceNames).map(([key, label]) => <option key={key} value={key}>{label}</option>)}{goalGroups.map(group => <option key={group.groupKey} value={'group:' + group.groupKey}>{group.group} · {group.activity === 'service' ? 'Serviço' : group.activity === 'merchandise' ? 'Mercadoria' : 'Sem classificação'}</option>)}</select></label>}<label>Objetivo {['services','category','sales_count','item_count','key_copies','plier_sharpening'].includes(form.kind) ? '(quantidade)' : '(R$)'}<input type="number" min="0" step={['services','category','sales_count','item_count','key_copies','plier_sharpening'].includes(form.kind) ? '1' : '0.01'} defaultValue={['services','category','sales_count','item_count','key_copies','plier_sharpening'].includes(form.kind) ? form.target : centsInput(form.target)} onChange={event => setForm({ ...form, target: ['services','category','sales_count','item_count','key_copies','plier_sharpening'].includes(form.kind) ? Number(event.target.value) : inputCents(event.target.value) })} /></label><label>Período<select value={form.period} onChange={event => setForm({ ...form, period: event.target.value as ManagementGoal['period'] })}><option value="daily">Diário</option><option value="monthly">Mensal</option><option value="custom">Personalizado</option></select></label>{form.period === 'custom' && <><label>Início<input type="date" value={form.startDate || ''} onChange={event => setForm({ ...form, startDate: event.target.value })} /></label><label>Fim<input type="date" value={form.endDate || ''} onChange={event => setForm({ ...form, endDate: event.target.value })} /></label></>}<label>Situação<select value={form.status} onChange={event => setForm({ ...form, status: event.target.value as ManagementGoal['status'] })}><option value="active">Ativa</option><option value="inactive">Inativa</option><option value="archived">Arquivada</option></select></label><div className="mg-full"><strong>Dias de funcionamento</strong><div className="mg-weekdays">{['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map((label, day) => <label className="mg-check" key={day}><input type="checkbox" checked={(form.workingDays || []).includes(day)} onChange={event => setForm({ ...form, workingDays: event.target.checked ? [...(form.workingDays || []), day] : (form.workingDays || []).filter(value => value !== day) })} /> {label}</label>)}</div></div><div className="mg-full mg-actions"><button className="btn btn-primary">Salvar meta</button></div></form></ReportModal>}</div>;
}
